import { useState } from 'react';
import { Button, Dialog, Stack, Text } from '@jinx-ui/react';

type DeleteProjectButtonProps = {
  onConfirm: () => void;
  projectName?: string;
};

export default function DeleteProjectButton({ onConfirm, projectName }: DeleteProjectButtonProps) {
  const [open, setOpen] = useState(false);

  const close = () => setOpen(false);

  const confirm = () => {
    setOpen(false);
    onConfirm();
  };

  return (
    <>
      <Button variant="danger" onClick={() => setOpen(true)}>
        Удалить проект
      </Button>

      <Dialog open={open} onClose={close} title="Удалить проект?" size="sm">
        <Stack gap="var(--jx-space-4)">
          <Text color="var(--jx-color-text-muted)">
            {projectName
              ? `Проект «${projectName}» и все его данные будут удалены безвозвратно. Это действие необратимо.`
              : 'Проект и все его данные будут удалены безвозвратно. Это действие необратимо.'}
          </Text>

          <Stack direction="row" gap="var(--jx-space-2)" justify="end">
            <Button variant="ghost" onClick={close}>
              Отмена
            </Button>
            <Button variant="danger" onClick={confirm} autoFocus>
              Удалить
            </Button>
          </Stack>
        </Stack>
      </Dialog>
    </>
  );
}

